var c=new LabPttController { RequireGrant=true };
c.Press(10); c.Grant(c.Epoch,40); c.Ready(c.Epoch,90); c.Frame(160,100);
var p=c.Evidence.Single(x=>x.Event=="PressAccepted");
var g=c.Evidence.Single(x=>x.Event=="GrantAccepted");
var r=c.Evidence.Single(x=>x.Event=="RadioReady");
Console.WriteLine($"{g.Ms-p.Ms}/{r.Ms-g.Ms}"); // 30/50

var c=new LabPttController(); c.Press(0); c.Ready(c.Epoch,10);
c.Frame(160,20); c.Frame(240,30); c.Release(40); c.Frame(80,50);
int beforeSent=c.SentSamples, beforeDrop=c.DroppedSamples;
c.Press(60); c.Frame(120,70); c.Ready(c.Epoch,80); c.Frame(200,90);
Console.WriteLine($"{c.SentSamples-beforeSent}/{c.DroppedSamples-beforeDrop}"); // 200/120
